import { execFileSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";
import { stripTypeScriptTypes } from "node:module";

const source = new URL(
  "../../plugins/harness/tooling/pnpm/rules/no-sensitive-content.ts",
  import.meta.url
);
const output = new URL(
  "../../plugins/harness/tooling/pnpm/runtime/no-sensitive-content.js",
  import.meta.url
);
const code = stripTypeScriptTypes(readFileSync(source, "utf-8")).replace(
  "\n */\nexport default {",
  '\n *\n * Generated by pnpm run rules:sync.\n * @type {import("markdownlint").Rule}\n */\nexport default {'
);
const contents = execFileSync(
  "oxfmt",
  ["--stdin-filepath", "no-sensitive-content.js"],
  {
    encoding: "utf-8",
    input: code
  }
);
if (process.argv.includes("--write")) {
  writeFileSync(output, contents);
} else if (readFileSync(output, "utf-8") !== contents) {
  process.stderr.write(
    "The packaged sensitive-content rule is out of sync. Run pnpm run rules:sync.\n"
  );
  process.exitCode = 1;
}
